"},{"path":"style.css","old_sha256":null,"content":"*{box-sizing:border-box}
body{margin:0;font-family:system-ui,sans-serif;background:#1c1e26;color:#e8e8f0}
header{padding:12px 16px;border-bottom:1px solid #333}
h1{margin:0 0 8px;font-size:18px}
.hud{display:flex;gap:16px;flex-wrap:wrap;font-size:13px;margin-bottom:10px}
.hud div{background:#262a36;padding:4px 10px;border-radius:6px}
.controls{display:flex;gap:8px}
button{background:#3a6df0;color:#fff;border:0;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:13px}
button:hover{background:#4a7df5}
#scene{position:relative;width:640px;height:560px;margin:24px auto;overflow:hidden}
.cube{position:absolute;width:48px;height:48px;cursor:pointer}
.cube .top{position:absolute;inset:0;background:#8a5a2b;transform:skewX(-30deg) scaleY(.5);transform-origin:50% 100%}
.cube .left{position:absolute;left:0;top:24px;width:24px;height:24px;background:#5e3d1c;transform:skewY(30deg);transform-origin:0 0}
.cube .right{position:absolute;right:0;top:24px;width:24px;height:24px;background:#74491f;transform:skewY(-30deg);transform-origin:100% 0}
.cube .label{position:absolute;left:0;top:26px;width:48px;text-align:center;font-size:10px;color:#fff;text-shadow:0 1px 2px #000;pointer-events:none}
.cube.ground .top{background:#3f7d3a}
.cube.ground .left{background:#2c5a29}
.cube.ground .right{background:#356b30}
.cube.player .top{background:#3a6df0}
.cube.player .left{background:#2749a8}
.cube.player .right{background:#2f57c4}
.cube.player .label{font-weight:700}
.cube:hover{filter:brightness(1.15)}
"},{"path":"world.js","old_sha256":null,"content":"const World = {
  size: 8,
  blocks: {},
  player: { x: 1, y: 1, z: 1, facing: 'east' },
  dirs: { east: [1, 0], south: [0, 1], west: [-1, 0], north: [0, -1] },
  key(x, y, z) { return x + ',' + y + ',' + z; },
  inBounds(x, y, z) { return x >= 0 && x < this.size && z >= 0 && z < this.size && y >= 0 && y <= 8; },
  get(x, y, z) { return this.blocks[this.key(x, y, z)] || null; },
  set(x, y, z, material) { this.blocks[this.key(x, y, z)] = { x, y, z, material }; },
  remove(x, y, z) { delete this.blocks[this.key(x, y, z)]; },
  init() {
    this.blocks = {};
    for (let x = 0; x < this.size; x++)
      for (let z = 0; z < this.size; z++)
        this.set(x, 0, z, 'ground');
    this.set(2, 1, 1, 'dirt');
    this.set(4, 1, 1, 'dirt');
    this.set(6, 1, 1, 'dirt');
    this.player = { x: 1, y: 1, z: 1, facing: 'east' };
  },
  turn(dir) {
    const order = ['north', 'east', 'south', 'west'];
    let i = order.indexOf(this.player.facing);
    i = (i + (dir === 'left' ? -1 : 1) + 4) % 4;
    this.player.facing = order[i];
  },
  move(dx, dz) {
    const nx = this.player.x + dx, nz = this.player.z + dz;
    if (!this.inBounds(nx, this.player.y, nz)) return false;
    this.player.x = nx; this.player.z = nz;
    return true;
  },
  target() {
    const d = this.dirs[this.player.facing];
    return { x: this.player.x + d[0], y: this.player.y, z: this.player.z + d[1] };
  }
};
"},{"path":"app.js","old_sha256":null,"content":"const scene = document.getElementById('scene');
const el = id => document.getElementById(id);
const TILE = 48, H = 24, OX = 320, OY = 240;

function project(x, y, z) {
  return { left: OX + (x - z) * (TILE / 2), top: OY + (x + z) * (H / 2) - y * TILE };
}

function render() {
  scene.innerHTML = '';
  const items = [];
  for (const k in World.blocks) {
    const b = World.blocks[k];
    items.push({ b, depth: b.x + b.z + b.y * 0.001 });
  }
  items.push({ b: { x: World.player.x, y: World.player.y, z: World.player.z, material: 'player' }, depth: World.player.x + World.player.z + 0.5 });
  items.sort((a, b) => a.depth - b.depth);
  for (const it of items) {
    const b = it.b;
    const p = project(b.x, b.y, b.z);
    const div = document.createElement('div');
    div.className = 'cube' + (b.material === 'ground' ? ' ground' : '') + (b.material === 'player' ? ' player' : '');
    div.style.left = p.left + 'px';
    div.style.top = p.top + 'px';
    div.style.zIndex = Math.round(b.x + b.z + b.y * 10);
    if (b.material !== 'player') div.setAttribute('data-block', b.x + ',' + b.y + ',' + b.z);
    div.innerHTML = '<div class="top"></div><div class="left"></div><div class="right"></div><div class="label">' + b.material + '</div>';
    scene.appendChild(div);
  }
  updateHUD();
}

function updateHUD() {
  el('world').textContent = 'world ' + World.size + 'x' + World.size;
  el('position').textContent = World.player.x + ',' + World.player.y + ',' + World.player.z;
  el('facing').textContent = World.player.facing;
}

function status(msg) { el('status').textContent = msg; }

function parseCoord(str) {
  const parts = str.split(',').map(Number);
  if (parts.length !== 3 || parts.some(n => !Number.isInteger(n))) return null;
  return { x: parts[0], y: parts[1], z: parts[2] };
}

function onCubeClick(e) {
  const c = e.target.closest('.cube');
  if (!c || c.classList.contains('player')) return;
  const coord = parseCoord(c.getAttribute('data-block'));
  if (!coord || !World.inBounds(coord.x, coord.y, coord.z)) { status('invalid coordinate'); return; }
  const b = World.get(coord.x, coord.y, coord.z);
  if (!b) { status('no block at ' + coord.x + ',' + coord.y + ',' + coord.z); return; }
  if (b.material === 'ground') { status('ground is nonremovable'); return; }
  World.remove(coord.x, coord.y, coord.z);
  status('removed ' + b.material + ' at ' + coord.x + ',' + coord.y + ',' + coord.z);
  render();
}

el('turn-left').addEventListener('click', () => { World.turn('left'); status('facing ' + World.player.facing); render(); });
el('turn-right').addEventListener('click', () => { World.turn('right'); status('facing ' + World.player.facing); render(); });
scene.addEventListener('click', onCubeClick);

World.init();
render();
"}]}
